'use strict';

/**
* Return the first index of an element in a single-precision floating-point strided array which is less than or equal to a specified search element.
*
* @module @stdlib/blas-ext-base-sindex-of-less-than-equal
*
* @example
* var Float32Array = require( '@stdlib/array-float32' );
* var sindexOfLessThanEqual = require( '@stdlib/blas-ext-base-sindex-of-less-than-equal' );
*
* var x = new Float32Array( [ 2.0, 3.0, 1.0, 4.0 ] );
*
* var idx = sindexOfLessThanEqual( x.length, 1.0, x, 1 );
* // returns 2
*
* @example
* var Float32Array = require( '@stdlib/array-float32' );
* var sindexOfLessThanEqual = require( '@stdlib/blas-ext-base-sindex-of-less-than-equal' );
*
* var x = new Float32Array( [ 2.0, 3.0, 1.0, 4.0 ] );
*
* var idx = sindexOfLessThanEqual.ndarray( x.length, 1.0, x, 1, 0 );
* // returns 2
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils-try-require' );
var isError = require( '@stdlib/assert-is-error' );
var main = require( './main.js' );


// MAIN //

var sindexOfLessThanEqual;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	sindexOfLessThanEqual = main;
} else {
	sindexOfLessThanEqual = tmp;
}


// EXPORTS //

module.exports = sindexOfLessThanEqual;

// exports: { "ndarray": "sindexOfLessThanEqual.ndarray" }
